var o=[{title:`Amplitude passiva e ativa`,text:`Pode conseguir mover o braço acima da cabeça com ajuda, mas ter dificuldade em levantá-lo até lá sozinho. Isso indica flexibilidade suficiente sem a mesma força ou coordenação nessa amplitude. Outras pessoas têm uma amplitude confortável realmente limitada e podem beneficiar de alongamento gradual ou de uma variação de exercício diferente.`},{title:`Teste os movimentos que usa`,text:`Um alcance controlado acima da cabeça, um agachamento confortável com o peso do corpo ou uma dobra de anca podem mostrar se um movimento do seu treino parece restringido. Compare os lados, mas não os force a igualar-se. O objetivo é detetar um limite prático. Não diagnostica a causa da rigidez, da dor articular nem de uma condição médica.`},{title:`Treine o controlo na amplitude que tem`,text:`Os círculos dinâmicos com os braços, os afundos controlados, as rotações torácicas e os movimentos lentos da anca permitem-lhe praticar amplitudes com controlo ativo. Os exercícios de força feitos numa amplitude confortável e progredidos ao longo do tempo também podem melhorar a mobilidade. O alongamento estático melhora a flexibilidade, mas por si só nem sempre desenvolve controlo.`},{title:`Não há uma amplitude perfeita única`,text:`As proporções do corpo, a estrutura das articulações, o historial de lesões e a competência afetam todos que movimentos parecem confortáveis. Não precisa de um agachamento profundo máximo nem de uma flexibilidade extrema do ombro para treinar bem. Escolha uma amplitude em que a técnica se mantenha estável e sem dor e construa a partir daí de forma gradual.`},{title:`Usar o TrainUp`,text:`Se uma zona do corpo limitar a sua amplitude, acrescente-a como limitação no Perfil, com uma nota. O plano escolhe então exercícios que se adaptam às suas limitações, ao seu nível e à sua coordenação. Cada página de exercício em Exercícios tem passos e notas de técnica. Pergunte a um médico ou fisioterapeuta sobre restrições que persistam, dor sem explicação ou sintomas que afetem a vida diária.`}];var i=[{label:`ACE 2026: mobilidade versus flexibilidade`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: orientações práticas de alongamento`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:o,sources:i};export{t as default,o as sections,i as sources};